=== FILE: deep_counter_props.sv ===
// Formal properties for deep_counter (task prj-784d6227b5:assertions-formal).
// Properties state the rules of interface_spec.md on the ports of the block:
// DC-RESET, DC-CLEAR, DC-COUNT, DC-HOLD, DC-RANGE, DC-CARRY; DC-PARAM is
// sampled at LIMIT = 1, 99 (default) and 127.
// Immediate assertions only (open Yosys front end); each $past is guarded by a
// first-cycle flag; each assertion has a single guarding if.
`timescale 1ns / 1ps

module deep_counter_checker #(
    parameter integer LIMIT = 99
) (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    wire [6:0] count;
    wire       carry;

    deep_counter #(.LIMIT(LIMIT)) dut (
        .clk  (clk),
        .rst_n(rst_n),
        .en   (en),
        .clr  (clr),
        .count(count),
        .carry(carry)
    );

    // First-cycle guard for $past.
    reg f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // DC-RANGE: count is never above LIMIT after reset (also the inductive invariant).
    always @(*) begin
        if (f_past_valid)
            assert (count <= LIMIT);
    end

    // DC-CARRY: carry is high exactly when en, not clr, and count equals LIMIT.
    always @(*) begin
        assert (carry == (en && !clr && (count == LIMIT)));
    end

    always @(posedge clk) begin
        // DC-RESET: reset low at an edge clears count.
        if (f_past_valid && !$past(rst_n))
            assert (count == 7'd0);

        // DC-CLEAR: clear wins over en.
        if (f_past_valid && $past(rst_n) && $past(clr))
            assert (count == 7'd0);

        // DC-COUNT (increment): below LIMIT, an enabled edge adds one.
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en) && ($past(count) < LIMIT))
            assert (count == $past(count) + 7'd1);

        // DC-COUNT (wrap): at LIMIT, an enabled edge returns count to 0.
        if (f_past_valid && $past(rst_n) && !$past(clr) && $past(en) && ($past(count) == LIMIT))
            assert (count == 7'd0);

        // DC-HOLD: neither clr nor en, count does not change.
        if (f_past_valid && $past(rst_n) && !$past(clr) && !$past(en))
            assert (count == $past(count));
    end

    // Scenarios the proof must still allow (vacuity / over-constraint check).
    always @(posedge clk) begin
        if (f_past_valid) begin
            // Carry seen: count reached LIMIT with en high and clr low.
            cover (rst_n && carry);
            // Wrap from LIMIT to 0.
            cover ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) == LIMIT) && (count == 7'd0));
            // Clear from a nonzero count while en is high.
            cover ($past(rst_n) && $past(clr) && $past(en) && ($past(count) != 7'd0));
            // Hold at a nonzero count.
            cover ($past(rst_n) && !$past(clr) && !$past(en) && ($past(count) != 7'd0));
            // Reset in the middle of a count.
            cover ($past(f_past_valid) && !$past(rst_n) && ($past(count) != 7'd0));
        end
    end
endmodule

module deep_counter_formal (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire clr
);
    // Only environment assumption: the block is reset in the first cycle,
    // since the spec states its range rule for the counter after reset.
    reg f_init_done = 1'b0;
    always @(posedge clk)
        f_init_done <= 1'b1;

    always @(*) begin
        if (!f_init_done)
            assume (!rst_n);
    end

    deep_counter_checker #(.LIMIT(1)) c_min (
        .clk(clk), .rst_n(rst_n), .en(en), .clr(clr)
    );

    deep_counter_checker #(.LIMIT(99)) c_def (
        .clk(clk), .rst_n(rst_n), .en(en), .clr(clr)
    );

    deep_counter_checker #(.LIMIT(127)) c_max (
        .clk(clk), .rst_n(rst_n), .en(en), .clr(clr)
    );
endmodule
=== END FILE ===
